DO $dadyoom$
DECLARE r RECORD; target_id uuid; prior text; nact integer; hasprogress integer;
BEGIN
 FOR r IN SELECT * FROM jsonb_to_recordset('[{"cid":"49c20b78-6022-419d-bcaa-ffaa31cb886a","unit":"1f15c698-d670-454d-87b2-4f71007ff248","n":1,"title":"الجمل وأشباه الجمل التي لها محل من الإعراب","passage":"قد تقع الجملة الفعلية خبرًا في «الطالبُ يراجعُ دروسه»؛ فالجملة «يراجع دروسه» في محل رفع خبر للمبتدأ. وقد يتعلق الجار والمجرور أو الظرف بمحذوف خبر في تركيب آخر. يعتمد الحكم على موقع الجملة ووظيفتها ولا تُعامل كل جملة تابعة على أنها صفة.","question":"ما محل «يراجع دروسه» في «الطالب يراجع دروسه»؟","correct":"في محل رفع خبر","wrong":["في محل نصب مفعول به","جملة لا محل لها قطعًا","فاعل مفرد"],"practice":"اكتب ثلاثة تراكيب لجملة ذات محل وشبه جملة خبر، مع تعليل الإعراب.","old":"DADYOOM_SD_G10_OFFICIAL_2026_V2"},{"cid":"49c20b78-6022-419d-bcaa-ffaa31cb886a","unit":"1f15c698-d670-454d-87b2-4f71007ff248","n":2,"title":"الإعراب التقديري للفعل المضارع","passage":"قد تُقدّر الحركة الإعرابية على آخر المضارع المعتل بالألف مثل «يسعى» في حالتي الرفع والنصب لتعذر ظهورها، وتظهر علامة الجزم بحذف حرف العلة عندما يقتضيه العامل. ينبغي التمييز بين الإعراب التقديري وحالة الجزم وعلاماتها.","question":"ما علامة رفع «يسعى» دون ناصب أو جازم؟","correct":"ضمة مقدرة على الألف","wrong":["ضمة ظاهرة","فتحة ظاهرة","حذف النون"],"practice":"أعرب ثلاثة أفعال مضارعة معتلة الآخر في حالات مختلفة مع تحديد سبب التقدير.","old":"DADYOOM_SD_G10_OFFICIAL_2026_V2"},{"cid":"49c20b78-6022-419d-bcaa-ffaa31cb886a","unit":"1f15c698-d670-454d-87b2-4f71007ff248","n":3,"title":"الجوازم","passage":"تؤثر أدوات الجزم في الفعل المضارع؛ فـ«لم يكتبْ» مضارع مجزوم بالسكون، و«لم يسعَ» مجزوم بحذف حرف العلة. تختلف علامة الجزم بين الصحيح والمعتل والأفعال الخمسة، ولذلك يجب تحديد بنية الفعل قبل كتابة العلامة.","question":"ما أثر «لم» في المضارع الصحيح الآخر؟","correct":"تجزمه","wrong":["ترفعه","تنصبه دائمًا","تحوله مصدرًا"],"practice":"ضع ست جمل بأدوات جزم مختلفة وأعرب الفعل في كل جملة.","old":"DADYOOM_SD_G10_OFFICIAL_2026_V2"},{"cid":"49c20b78-6022-419d-bcaa-ffaa31cb886a","unit":"1f15c698-d670-454d-87b2-4f71007ff248","n":4,"title":"التوابع","passage":"التوابع أربعة أبواب مشهورة: النعت والعطف والتوكيد والبدل، وتلحق متبوعها في الإعراب بحسب نوعها وحكمها. في «حضر الطالبُ المجتهدُ» «المجتهدُ» نعت مرفوع، بينما «حضر الطالبُ ومحمدٌ» تتضمن عطفًا.","question":"ما نوع «المجتهد» في «حضر الطالب المجتهد»؟","correct":"نعت","wrong":["بدل في كل سياق","حال","مفعول مطلق"],"practice":"اكتب جملة لكل تابع مع ضبط التابع والمتبوع وشرح العلاقة.","old":"DADYOOM_SD_G10_OFFICIAL_2026_V2"},{"cid":"49c20b78-6022-419d-bcaa-ffaa31cb886a","unit":"1f15c698-d670-454d-87b2-4f71007ff248","n":5,"title":"المجرد والمزيد والبحث في المعاجم","passage":"الفعل المجرد حروفه أصلية مثل «كتب»، ويزاد على بنيته في «استكتب» أحرف تساهم في اختلاف الدلالة. لفهم الجذر تُحذف الزيادات على قواعد الصرف، ثم يرجع الباحث إلى المعجم مرتّبًا وفق نظامه؛ لا يحذف الحروف اعتباطًا.","question":"ما الجذر الثلاثي للفعل «استكتب»؟","correct":"كتب","wrong":["است","كتاب","كاتب"],"practice":"حلل خمسة أفعال مجردة ومزيدة وحدد مداخلها في معجم مناسب.","old":"DADYOOM_SD_G10_OFFICIAL_2026_V2"},{"cid":"49c20b78-6022-419d-bcaa-ffaa31cb886a","unit":"1f15c698-d670-454d-87b2-4f71007ff248","n":6,"title":"الميزان الصرفي","passage":"يوزن الجذر الثلاثي بحروف «فعل»، فتكون كلمة «كاتب» على وزن «فاعل» والجذر «كتب»، بينما «مكتوب» على وزن «مفعول». تساعد الموازنة في معرفة الحروف الأصلية والزائدة، مع مراعاة قواعد الإعلال والإبدال والتضعيف في الأبواب الأوسع.","question":"ما وزن «مكتوب»؟","correct":"مفعول","wrong":["فاعل","فعول","مفعال"],"practice":"زن ست كلمات ثم بيّن الحروف الأصلية والزائدة.","old":"DADYOOM_SD_G10_OFFICIAL_2026_V2"},{"cid":"49c20b78-6022-419d-bcaa-ffaa31cb886a","unit":"1f15c698-d670-454d-87b2-4f71007ff248","n":7,"title":"صيغة النسب","passage":"النسبة الصرفية إلحاق ياء مشددة وكسر ما قبلها غالبًا، مثل «وطنِيّ» من «وطن»، مع تغييرات خاصة في أنواع الأسماء الأخرى. يراعى ضبط أصل الكلمة قبل اشتقاق الصفة حتى لا تختلط بياء المتكلم.","question":"أي صيغة نسبة صحيحة إلى «وطن»؟","correct":"وطنِيّ","wrong":["وطنون","وَطْنًا","وطنات"],"practice":"اكتب النسب إلى ستة أسماء متنوعة مع توظيفها في جمل.","old":"DADYOOM_SD_G10_OFFICIAL_2026_V2"},{"cid":"49c20b78-6022-419d-bcaa-ffaa31cb886a","unit":"1f15c698-d670-454d-87b2-4f71007ff248","n":8,"title":"النسب إلى المختوم بتاء التأنيث","passage":"عند النسب إلى اسم مختوم بتاء التأنيث تُحذف التاء المربوطة في كثير من الأمثلة القياسية، مثل «مكة» فتكون «مكّيّ» بعد التغيير المناسب للأصل، ولا نضيف ياء النسب إلى التاء كما هي دون تحليل.","question":"ما الحرف الذي يُحذف من آخر الاسم المختوم بتاء التأنيث في النسبة المعتادة؟","correct":"التاء المربوطة","wrong":["الجذر بالكامل","حرف الجر","أل التعريف دائمًا"],"practice":"انسب إلى ثلاثة أسماء مختومة بتاء مربوطة وفسر التغييرات.","old":"DADYOOM_SD_G10_OFFICIAL_2026_V2"},{"cid":"49c20b78-6022-419d-bcaa-ffaa31cb886a","unit":"1f15c698-d670-454d-87b2-4f71007ff248","n":9,"title":"النسب إلى المقصور","passage":"آخر الاسم المقصور ألف لازمة مثل «فتى»؛ وتتغير معالجتها في النسب بحسب طول الاسم وموقع الألف، فلا تضاف ياء النسبة آليًا إلى الرسم الأصلي. تُراجع القاعدة الصرفية والأصل المعجمي عند وجود احتمالين.","question":"ما نوع الاسم «فتى» من حيث آخره؟","correct":"مقصور","wrong":["ممدود","منقوص","صحيح فقط"],"practice":"قارن اسمين مقصورين مختلفَي الطول مع صيغة النسب الموثقة.","old":"DADYOOM_SD_G10_OFFICIAL_2026_V2"},{"cid":"49c20b78-6022-419d-bcaa-ffaa31cb886a","unit":"1f15c698-d670-454d-87b2-4f71007ff248","n":10,"title":"النسب إلى المنقوص","passage":"المنقوص اسم معرب آخره ياء لازمة مكسور ما قبلها مثل «القاضي»، وقد تتغير الياء عند النسب إليه وفق أحكام باب النسب، مع مراعاة طول الاسم وأصله. لا نخلط بين الياء الأصلية وياء النسب المشددة.","question":"أي كلمة اسم منقوص؟","correct":"القاضي","wrong":["صحراء","فتى","كتاب"],"practice":"اكتب أمثلة موثقة للنسب إلى أسماء منقوصة وبيّن موضع تغيير الياء.","old":"DADYOOM_SD_G10_OFFICIAL_2026_V2"},{"cid":"49c20b78-6022-419d-bcaa-ffaa31cb886a","unit":"1f15c698-d670-454d-87b2-4f71007ff248","n":11,"title":"النسب إلى الممدود","passage":"تنتهي الأسماء الممدودة بهمزة بعد ألف زائدة مثل «صحراء»، ويختلف النسب بحسب نوع الهمزة: أصلية أو منقلبة أو زائدة للتأنيث، فلا يكفي النظر للحروف الثلاثة الأخيرة دون معرفة الأصل الصرفي.","question":"ما السمة الكتابية للاسم الممدود؟","correct":"همزة يسبقها ألف زائدة","wrong":["ألف مقصورة","ياء لازمة مكسور ما قبلها","تاء مفتوحة"],"practice":"صنف أسماء ممدودة مختلفة بحسب نوع الهمزة واستخرج النسب الصحيح من مرجع.","old":"DADYOOM_SD_G10_OFFICIAL_2026_V2"},{"cid":"49c20b78-6022-419d-bcaa-ffaa31cb886a","unit":"1f15c698-d670-454d-87b2-4f71007ff248","n":12,"title":"النسب إلى ما فيه ياء مشددة","passage":"تتطلب النسبة إلى اسم في بنائه ياء مشددة معرفة وزن الكلمة وموقع تلك الياء وعدد حروف الاسم، وقد تؤدي القواعد إلى حذف أو تغيير بعض الحروف. لا تكرر الياء المشددة آليًا قبل فحص أصل الكلمة.","question":"ما أول خطوة للنسب إلى اسم فيه ياء مشددة؟","correct":"تحليل الوزن وأصل الياء وموقعها","wrong":["عد المقاطع من النهاية فقط","حذف الياء دائمًا","زيادة ألف"],"practice":"اختر ثلاثة أسماء ذات ياء مشددة وفسر صيغ النسب المعجمية إليها.","old":"DADYOOM_SD_G10_OFFICIAL_2026_V2"},{"cid":"49c20b78-6022-419d-bcaa-ffaa31cb886a","unit":"1f15c698-d670-454d-87b2-4f71007ff248","n":13,"title":"النسب إلى وزن فعيلة","passage":"عند النسبة إلى الاسم على وزن «فعيلة» قد تقع تغييرات صرفية في الياء أو بنية الاسم بحسب شروط الباب، مثل النسب إلى «مدينة» في الاستعمال المعروف «مدنيّ»، ولا يجوز تعميم صورة واحدة على كل الأسماء المشابهة دون تحقق.","question":"ما الذي يجب ملاحظته في النسب إلى «فعيلة»؟","correct":"وزن الاسم وحروفه وشروط التغيير","wrong":["طول الجملة","اسم الشهر","حرف الجر"],"practice":"اكتب النسب الموثق إلى ثلاثة أسماء على وزن فعيلة مع تحليل الفروق.","old":"DADYOOM_SD_G10_OFFICIAL_2026_V2"},{"cid":"49c20b78-6022-419d-bcaa-ffaa31cb886a","unit":"1f15c698-d670-454d-87b2-4f71007ff248","n":14,"title":"النسب إلى الاسم الثلاثي مكسور العين","passage":"عين الكلمة في الصرف هي حرف الجذر الثاني، وقد يتطلب النسب إلى اسم ثلاثي مكسور العين مراعاة حركات البناء وتخفيف موضع الكسرة وفق قاعدة الباب. نزن الكلمة أولًا ثم نتثبت من صورة النسب بدلاً من الحكم بحسب الرسم وحده.","question":"ما المقصود بعين الكلمة في الجذر الثلاثي؟","correct":"الحرف الأصلي الثاني","wrong":["الأول","الثالث","ياء النسب"],"practice":"زن خمسة أسماء ثلاثية واضبط حركتها وانسب إليها بالرجوع إلى مرجع صرفي.","old":"DADYOOM_SD_G10_OFFICIAL_2026_V2"},{"cid":"49c20b78-6022-419d-bcaa-ffaa31cb886a","unit":"1f15c698-d670-454d-87b2-4f71007ff248","n":15,"title":"النسب إلى المركب","passage":"قد يكون المركب إضافيًا مثل «عبد الله»، أو مزجيًا في أسماء معلومة، ويختلف اشتقاق النسب إلى المركبات بحسب النوع والاستعمال والسياق. قبل الاشتقاق نحدد حدود أجزاء الاسم وأيها يحتفظ بمعناه بعد النسب.","question":"ما الخطوة الأساسية قبل النسب إلى تركيب إضافي؟","correct":"تحديد نوع المركب وأجزائه","wrong":["حذف جميع الأجزاء","زيادة تنوين دائمًا","الاعتماد على حرف واحد"],"practice":"حلل ثلاثة أسماء مركبة واستخرج النسب الموثق إليها مع السبب.","old":"DADYOOM_SD_G10_OFFICIAL_2026_V2"},{"cid":"49c20b78-6022-419d-bcaa-ffaa31cb886a","unit":"1f15c698-d670-454d-87b2-4f71007ff248","n":16,"title":"النسب إلى المثنى والجمع","passage":"يتطلب النسب إلى صيغة مثنى أو جمع معرفة المفرد والعلامة الصرفية، وقد يُرد الاسم إلى مفرده في النسبة بحسب نوع الجمع والحكم. في «الكاتبان» يميز المتعلم مفرد «كاتب» من علامة التثنية قبل التحليل.","question":"ما مفرد «الكاتبان»؟","correct":"كاتب","wrong":["كتاب","مكتوب","كاتبة"],"practice":"وازن بين صيغ مثنى وجمع سالم وتكسير ثم طبق أحكام النسب.","old":"DADYOOM_SD_G10_OFFICIAL_2026_V2"},{"cid":"49c20b78-6022-419d-bcaa-ffaa31cb886a","unit":"1f15c698-d670-454d-87b2-4f71007ff248","n":17,"title":"لا التي تعمل عمل ليس","passage":"تعمل «لا» عمل «ليس» بشروط نحوية معروفة في بعض التراكيب والأساليب، فترفع الاسم وتنصب الخبر في مواضع العمل. يختلف هذا الاستعمال عن «لا النافية للجنس» وعن «لا» التي لا تعمل، ويُرجع في تعيين النوع إلى تركيب الجملة.","question":"ما العمل الإعرابي لـ«لا» العاملة عمل «ليس»؟","correct":"ترفع الاسم وتنصب الخبر","wrong":["تجزم فعلين","تنصب الاسم وترفع الخبر دائمًا","تجر الاسم"],"practice":"حلل مثالين موثقين لعمل «لا» عمل ليس مع شروطهما.","old":"DADYOOM_SD_G10_OFFICIAL_2026_V2"},{"cid":"49c20b78-6022-419d-bcaa-ffaa31cb886a","unit":"1f15c698-d670-454d-87b2-4f71007ff248","n":18,"title":"لا النافية للجنس","passage":"تنفي «لا النافية للجنس» الخبر عن جنس الاسم الذي يليها في تركيب مثل «لا طالبَ مهملٌ» بحسب الشروط الإعرابية المناسبة، وتعمل عمل إنّ فتنصب الاسم وترفع الخبر. لا تعمل «لا» هذا العمل في كل استعمالاتها.","question":"ما عمل «لا» النافية للجنس؟","correct":"تنصب اسمها وترفع خبرها","wrong":["ترفع الاثنين","تجزم المضارع","تعمل عمل كان"],"practice":"أنشئ ثلاثة تراكيب للا النافية للجنس واضبط الاسم والخبر.","old":"DADYOOM_SD_G10_OFFICIAL_2026_V2"},{"cid":"49c20b78-6022-419d-bcaa-ffaa31cb886a","unit":"1f15c698-d670-454d-87b2-4f71007ff248","n":19,"title":"أنواع لا - مراجعة","passage":"تأتي «لا» للنفي أو النهي أو نفي الجنس أو وظائف أخرى تبعًا للمقام والعمل؛ فـ«لا تكتبْ» في سياق الطلب ناهية تجزم المضارع، و«لا طالبَ غائبٌ» قد تكون نافية للجنس، والتمييز يقتضي النظر إلى ما يلي الأداة.","question":"أي «لا» في «لا تكتبْ» عندما يكون طلبًا؟","correct":"لا الناهية الجازمة","wrong":["لا النافية للجنس","لا العاطفة","لا الزائدة دائمًا"],"practice":"اكتب ستة أمثلة مختلفة لـ«لا» وصنفها بحسب المعنى والإعراب.","old":"DADYOOM_SD_G10_OFFICIAL_2026_V2"},{"cid":"49c20b78-6022-419d-bcaa-ffaa31cb886a","unit":"1f15c698-d670-454d-87b2-4f71007ff248","n":20,"title":"همزتا القطع والوصل","passage":"تثبت همزة القطع نطقًا وكتابة في الابتداء والدرج مثل «أحمد»، أما همزة الوصل فتثبت عند الابتداء وتسقط في درج الكلام مثل «استمع». تحديدها يتطلب النظر إلى بنية الكلمة والباب الصرفي لا عدد حروفها فقط.","question":"ما نوع همزة «استمع»؟","correct":"همزة وصل","wrong":["همزة قطع","متطرفة","متوسطة"],"practice":"اجمع عشرة أمثلة متنوعة، وصنف همزتها مع تعليل الحكم.","old":"DADYOOM_SD_G10_OFFICIAL_2026_V2"},{"cid":"49c20b78-6022-419d-bcaa-ffaa31cb886a","unit":"1f15c698-d670-454d-87b2-4f71007ff248","n":21,"title":"اسم الفعل","passage":"اسم الفعل كلمة تدل على معنى الفعل وتعمل عمله في مواضع لكنها لا تقبل علاماته الزمنية المعتادة؛ في «صَهْ» اسم فعل أمر بمعنى اسكت. وتختلف أسماء الأفعال في معناها وزمن دلالتها، ولا تُعرب كأفعال متصرفة.","question":"ما معنى اسم الفعل «صهْ»؟","correct":"اسكت","wrong":["اكتب","اذهب","اجلس"],"practice":"اختر ثلاثة أسماء أفعال موثقة مع معنى كل واحد ومثال في جملة.","old":"DADYOOM_SD_G10_OFFICIAL_2026_V2"},{"cid":"49c20b78-6022-419d-bcaa-ffaa31cb886a","unit":"1f15c698-d670-454d-87b2-4f71007ff248","n":22,"title":"العدد","passage":"تختلف أحكام العدد والمعدود حسب المجال العددي والجنس والتركيب؛ في «ثلاثة كتبٍ» العدد من ثلاثة إلى عشرة يخالف المعدود المذكر ويأتي المعدود جمعًا مجرورًا بالإضافة. لا نعمم حكم هذه الأعداد على العددين واحد واثنين.","question":"ما المعدود في «ثلاثة كتب»؟","correct":"كتب","wrong":["ثلاثة","من","في"],"practice":"اكتب خمسة تراكيب عددية متنوعة مع ضبط العدد والمعدود وتعليل المطابقة.","old":"DADYOOM_SD_G10_OFFICIAL_2026_V2"},{"cid":"49c20b78-6022-419d-bcaa-ffaa31cb886a","unit":"1f15c698-d670-454d-87b2-4f71007ff248","n":23,"title":"بعض الأخطاء الشائعة","passage":"يمكن تصويب الخطأ اللغوي بفحص القاعدة والسياق لا باستبدال كلمة على الظن؛ نميز الخطأ الإملائي من النحوي والدلالي. في «هؤلاءِ الطلابُ مجتهدون» يُراعى ضبط اسم الإشارة والجمع والخبر، ويُرجع للاستخدام الفصيح الموثق عند الالتباس.","question":"ما الخطوة الصحيحة قبل الحكم على عبارة بأنها خطأ؟","correct":"فحص السياق والقاعدة من مرجع موثوق","wrong":["تغييرها عشوائيًا","الاعتماد على السماع وحده","حذف الكلمات"],"practice":"راجع خمس جمل مكتوبة، وصنف الأخطاء مع اقتراح تصحيح وتعليل.","old":"DADYOOM_SD_G10_OFFICIAL_2026_V2"}]'::jsonb)
 AS x(cid uuid,unit uuid,n integer,title text,passage text,question text,correct text,wrong text[],practice text,old text)
 LOOP
  SELECT l.id,l.content INTO STRICT target_id,prior
  FROM public.lessons l JOIN public.units u ON u.id=l.unit_id
  JOIN public.grades g ON g.id=u.grade_id
  JOIN public.curricula c ON c.id=g.curriculum_id
  JOIN public.countries co ON co.id=c.country_id
  WHERE co.code='SD' AND c.id=r.cid
    AND g.grade_number=10 AND u.semester IS NULL AND u.id=r.unit
    AND l.sort_order=r.n AND l.title=r.title AND l.status='published'
  FOR UPDATE OF l;

  SELECT count(*) INTO hasprogress FROM public.student_lesson_progress WHERE lesson_id=target_id;
  IF hasprogress<>0 THEN RAISE EXCEPTION 'SD_G10_HAS_PROGRESS_%',r.title; END IF;
  SELECT count(*) INTO hasprogress FROM public.lesson_activity_attempts att
    JOIN public.lesson_activities a ON a.id=att.activity_id WHERE a.lesson_id=target_id;
  IF hasprogress<>0 THEN RAISE EXCEPTION 'SD_G10_HAS_ATTEMPTS_%',r.title; END IF;
  IF char_length(coalesce(prior,''))>=350 THEN RAISE EXCEPTION 'SD_G10_ALREADY_CONTENT_%',r.title; END IF;
  SELECT count(*) INTO nact FROM public.lesson_activities
    WHERE lesson_id=target_id AND content->>'origin'=r.old AND answer='{}'::jsonb;
  IF nact<>3 THEN RAISE EXCEPTION 'SD_G10_EXPECTED_3_PLACEHOLDERS_%',r.title; END IF;

  UPDATE public.lessons SET
    content='ضاديوم — إثراء تعليمي أصلي للسنة الرابعة الإعدادية في موريتانيا. هذا ليس نص الكتاب المعتمد ولا تأكيدًا لمطابقة جميع الفصول؛ الاسم مستورد ويلزم تحقق وزاري.'
    ||E'\n\n'||'عنوان الدرس: '||r.title
    ||E'\n\n'||'هدف التعلم: أن يشرح المتعلم فكرة أو قاعدة من المجال، ويحلل قرينة أو شاهدًا صحيح النسبة، ويكتب استجابة جديدة تستند إلى دليل.'
    ||E'\n\n'||'شرح وتطبيق أصلي: '||r.passage
    ||E'\n\n'||'سؤال فهم: '||r.question
    ||E'\n\n'||'تطبيق كتابي مستقل: '||r.practice
    ||E'\n\n'||'التمايز: دعم بقائمة مفردات وخطوات تحليل أساسية، ومستوى متوسط يبرر الاختيار، ومستوى متقدم يقارن بين تفسيرين أو يختبر دقة المصدر. يتولى المعلم مراجعة مهام الكتابة.'
    ||E'\n\n'||'تحذير المصدر: لا تُنسب أمثلة ضاديوم إلى شاعر أو مؤرخ أو نص ديني؛ راجع المصدر المعتمد أولًا.'
    ||E'\n\n'||'المحتوى السابق المحفوظ: '||coalesce(prior,''),
    updated_at=now() WHERE id=target_id;

  UPDATE public.lesson_activities SET
    prompt='اقرأ النص التدريبي المستقل، واستخرج منه الفكرة أو الشاهد الذي تستند إليه الإجابة.',
    content=content||jsonb_build_object('origin','DADYOOM_SD_G10_GRAMMAR_ORIGINAL_23_20261009','previousOrigin',r.old,
      'text',r.passage,'notOfficialBook',true,'sourceVerification','pending')
    WHERE lesson_id=target_id AND activity_type='reading'
      AND content->>'origin'=r.old AND answer='{}'::jsonb;

  UPDATE public.lesson_activities SET prompt=r.question,
    content=content||jsonb_build_object('origin','DADYOOM_SD_G10_GRAMMAR_ORIGINAL_23_20261009','previousOrigin',r.old,
       'text',r.question,'notOfficialBook',true,'sourceVerification','pending',
       'options',CASE (r.n%4)
       WHEN 0 THEN jsonb_build_array(r.correct,r.wrong[1],r.wrong[2],r.wrong[3])
       WHEN 1 THEN jsonb_build_array(r.wrong[1],r.correct,r.wrong[2],r.wrong[3])
       WHEN 2 THEN jsonb_build_array(r.wrong[1],r.wrong[2],r.correct,r.wrong[3])
       ELSE jsonb_build_array(r.wrong[1],r.wrong[2],r.wrong[3],r.correct) END),
    answer=jsonb_build_object('correct',r.correct)
    WHERE lesson_id=target_id AND activity_type='multiple_choice'
      AND content->>'origin'=r.old AND answer='{}'::jsonb;

  UPDATE public.lesson_activities SET prompt=r.practice,
    content=content||jsonb_build_object('origin','DADYOOM_SD_G10_GRAMMAR_ORIGINAL_23_20261009','previousOrigin',r.old,
     'text',r.practice,'notOfficialBook',true,'sourceVerification','pending',
     'humanReviewRequired',true)
    WHERE lesson_id=target_id AND activity_type='writing'
      AND content->>'origin'=r.old AND answer='{}'::jsonb;

  SELECT count(*) INTO nact FROM public.lesson_activities
   WHERE lesson_id=target_id AND content->>'origin'='DADYOOM_SD_G10_GRAMMAR_ORIGINAL_23_20261009';
  IF nact<>3 THEN RAISE EXCEPTION 'SD_G10_ACTIVITY_UPDATE_FAILED_%',r.title; END IF;
 END LOOP;
END $dadyoom$;